-- Run read-only against CM Train. Export the courses JSON array only.
-- Includes answer keys: use an authorized operator, keep the file private,
-- upload it only to the authenticated Support Hub course importer, never Git.
select jsonb_agg(jsonb_build_object('id',c.id,'versionId',v.id,'versionNumber',v.version_number,'title',c.title,'description',c.description,'category',c.category,'durationMinutes',c.estimated_duration_minutes,'units',(
select jsonb_agg(jsonb_build_object('id',b.id,'type',b.block_type,'title',b.title,'body',b.body->>'content','script',b.body->>'script','attestation',b.body->>'attestation_text','videoUrl',b.video_url,'quiz',(select jsonb_build_object('passingScore',q.passing_score_percent,'maxAttempts',q.max_attempts,'kind',q.quiz_kind,'questions',(select jsonb_agg(jsonb_build_object('id',qq.id,'prompt',qq.question_text,'type',qq.question_type,'points',qq.points,'options',(select jsonb_agg(jsonb_build_object('id',a.id,'text',a.answer_text,'correct',a.is_correct) order by a.sort_order,a.id) from public.quiz_answers a where a.question_id=qq.id)) order by qq.sort_order,qq.id) from public.quiz_questions qq where qq.quiz_id=q.id)) from public.quizzes q where q.course_block_id=b.id)) order by b.sort_order,b.id) from public.course_blocks b where b.course_version_id=v.id
)) order by c.id) as courses from public.courses c join public.course_versions v on v.id=c.current_version_id where c.organization_id is null and c.status='published';
